package br.com.spbank.investimento.application.service;
import static org.assertj.core.api.Assertions.*;
import static org.mockito.Mockito.*;
import br.com.spbank.investimento.application.model.*;
import br.com.spbank.investimento.application.port.out.*;
import java.math.BigDecimal;
import java.time.*;
import java.util.*;
import org.junit.jupiter.api.*;
class InvestmentValuationCalculatorTest {
    private final UUID customer=UUID.randomUUID(),account=UUID.randomUUID(),fundId=UUID.randomUUID(),cdbId=UUID.randomUUID();
    private final InvestmentPersistence persistence=mock(InvestmentPersistence.class);
    private final InvestmentReferenceData reference=mock(InvestmentReferenceData.class);
    private final Set<LocalDate> holidays=new HashSet<>();
    private final List<InvestmentCdiPeriod> periods=new ArrayList<>();
    private final InvestmentBusinessCalendar calendar=new InvestmentBusinessCalendar(persistence);
    private final InvestmentValuationCalculator calculator=new InvestmentValuationCalculator(persistence,reference,calendar);
    private InvestmentQuote quote;
    private final LocalDate applied=LocalDate.of(2026,10,9);
    @BeforeEach void setup(){holidays.add(LocalDate.of(2026,10,12));when(persistence.holidays(any(),any())).thenAnswer(i->Set.copyOf(holidays));when(reference.cdiPeriods(any(),any())).thenAnswer(i->List.copyOf(periods));when(persistence.quote(eq(fundId),any())).thenAnswer(i->Optional.ofNullable(quote));periods.add(rate("2026-01-01","2027-12-31","1.001","A"));quote=new InvestmentQuote(fundId,LocalDate.of(2026,10,14),decimal("10.55"));}
    @Test void fundUsesLatestDatedQuoteAndPreservesAcquisitionData(){var position=fund();var value=calculator.calculate(position,LocalDate.of(2026,10,15));assertThat(value.grossValue()).isEqualByComparingTo("1055.00");assertThat(value.grossEarnings()).isEqualByComparingTo("55.00");assertThat(value.referenceDate()).isEqualTo(LocalDate.of(2026,10,15));assertThat(value.calculatedThrough()).isEqualTo(LocalDate.of(2026,10,14));assertThat(position.unitPrice()).isEqualByComparingTo("10");assertThat(value.currentQuote().price()).isEqualByComparingTo("10.55");verifyNoInteractions(reference);}
    @Test void negativeFundReturnsAreNotClampedToZero(){quote=new InvestmentQuote(fundId,applied,decimal("9.10"));var value=calculator.calculate(fund(),applied);assertThat(value.grossValue()).isEqualByComparingTo("910.00");assertThat(value.grossEarnings()).isEqualByComparingTo("-90.00");}
    @Test void missingQuoteIsUnavailableWithoutInventedZero(){quote=null;var value=calculator.calculate(fund(),applied);assertThat(value.status()).isEqualTo(InvestmentValuation.Status.DATA_UNAVAILABLE);assertThat(value.grossValue()).isNull();assertThat(value.grossEarnings()).isNull();assertThat(value.errorCode()).isEqualTo("INVESTMENT_QUOTE_MISSING");}
    @Test void futureQuoteCannotValueAnEarlierDate(){quote=new InvestmentQuote(fundId,applied.plusDays(1),decimal("11"));assertThat(calculator.calculate(fund(),applied).errorCode()).isEqualTo("INVESTMENT_QUOTE_DATE");}
    @Test void quoteOlderThanAcquisitionIsRejected(){quote=new InvestmentQuote(fundId,applied.minusDays(1),decimal("11"));assertThat(calculator.calculate(fund(),applied).errorCode()).isEqualTo("INVESTMENT_QUOTE_DATE");}
    @Test void cdbAccrues110PercentOnlyOnBusinessDaysAfterApplication(){var value=calculator.calculate(cdb(360),LocalDate.of(2026,10,14));assertThat(value.grossValue()).isEqualByComparingTo("1002.20");assertThat(value.grossEarnings()).isEqualByComparingTo("2.20");assertThat(value.accruedBusinessDays()).isEqualTo(2);assertThat(value.calculatedThrough()).isEqualTo(LocalDate.of(2026,10,14));assertThat(value.currentQuote()).isNull();}
    @Test void holidayAfterAWeekendAlsoDoesNotAccrue(){var value=calculator.calculate(cdb(360),LocalDate.of(2026,10,12));assertThat(value.grossValue()).isEqualByComparingTo("1000.00");assertThat(value.accruedBusinessDays()).isZero();verify(reference,never()).cdiPeriods(any(),any());}
    @Test void exactMobileHolidayIsExcluded(){holidays.add(LocalDate.of(2026,10,13));var value=calculator.calculate(cdb(360),LocalDate.of(2026,10,14));assertThat(value.accruedBusinessDays()).isEqualTo(1);assertThat(value.grossValue()).isEqualByComparingTo("1001.10");}
    @Test void rateVersionChangesAreCompoundedAndTraced(){periods.clear();periods.add(rate("2026-10-10","2026-10-13","1.001","A"));periods.add(rate("2026-10-14","2026-10-31","1.002","B"));var value=calculator.calculate(cdb(360),LocalDate.of(2026,10,14));assertThat(value.grossValue()).isEqualByComparingTo("1003.30");assertThat(value.cdiPeriods().stream().map(p->p.version()).toList()).containsExactly("A","B");}
    @Test void roundsOnlyAfterCompoundingSoSmallDailyAccrualIsPreserved(){periods.clear();periods.add(rate("2026-01-01","2027-12-31","1.000004","SMALL"));var value=calculator.calculate(cdb(360),LocalDate.of(2026,10,14));assertThat(value.grossValue()).isEqualByComparingTo("1000.01");assertThat(value.grossEarnings()).isEqualByComparingTo("0.01");}
    @Test void full252BusinessDaysMatchesIndependentExactRationalReference(){holidays.clear();var start=LocalDate.of(2026,1,1);var through=start;int count=0;while(count<252){through=through.plusDays(1);if(through.getDayOfWeek()!=DayOfWeek.SATURDAY&&through.getDayOfWeek()!=DayOfWeek.SUNDAY)count++;}var position=cdbAt(start,start.plusDays(360));var value=calculator.calculate(position,through);assertThat(value.accruedBusinessDays()).isEqualTo(252);assertThat(value.grossValue()).isEqualByComparingTo("1319.23");}
    @Test void maturityStopsAccrualEvenWhenItFallsOnSunday(){var position=cdb(9);var value=calculator.calculate(position,LocalDate.of(2026,10,30));assertThat(value.accruedBusinessDays()).isEqualTo(4);assertThat(value.calculatedThrough()).isEqualTo(LocalDate.of(2026,10,16));assertThat(value.grossValue()).isEqualByComparingTo("1004.41");}
    @Test void applicationDayDoesNotEarnInterest(){var value=calculator.calculate(cdb(360),applied);assertThat(value.grossValue()).isEqualByComparingTo("1000.00");assertThat(value.accruedBusinessDays()).isZero();verify(reference,never()).cdiPeriods(any(),any());}
    @Test void missingBusinessDayFactorIsUnavailableAndNeverAssumedZero(){periods.clear();periods.add(rate("2026-10-14","2027-01-01","1.001","GAP"));var value=calculator.calculate(cdb(360),LocalDate.of(2026,10,14));assertThat(value.errorCode()).isEqualTo("INVESTMENT_CDI_MISSING");assertThat(value.grossValue()).isNull();}
    @Test void overlappingVersionsAreRejectedInsteadOfChoosingSilently(){periods.add(rate("2026-10-13","2026-10-14","1.002","OVERLAP"));var value=calculator.calculate(cdb(360),LocalDate.of(2026,10,14));assertThat(value.errorCode()).isEqualTo("INVESTMENT_CDI_OVERLAP");assertThat(value.grossValue()).isNull();}
    @Test void negativeCdiFactorCanProduceALoss(){periods.clear();periods.add(rate("2026-01-01","2027-12-31","0.999","NEGATIVE"));var value=calculator.calculate(cdb(360),LocalDate.of(2026,10,13));assertThat(value.grossValue()).isEqualByComparingTo("998.90");assertThat(value.grossEarnings()).isEqualByComparingTo("-1.10");}
    @Test void invalidProductFactorDoesNotProduceANegativeGross(){periods.clear();periods.add(rate("2026-01-01","2027-12-31","0.01","INVALID"));assertThat(calculator.calculate(cdb(360),LocalDate.of(2026,10,13)).errorCode()).isEqualTo("INVESTMENT_CDI_INVALID");}
    @Test void historicalLotUsesContractedPercentageWithoutReadingCurrentCatalog(){var value=calculator.calculate(cdb(360),LocalDate.of(2026,10,13));assertThat(value.grossValue()).isEqualByComparingTo("1001.10");verify(persistence,never()).product(any(),anyBoolean());}
    @Test void sameInputsReproduceSameFingerprintWithoutPersistingAnything(){var position=cdb(360);var date=LocalDate.of(2026,10,14);var first=calculator.calculate(position,date);var next=calculator.calculate(position,date);assertThat(next).isEqualTo(first);verify(reference,never()).saveValuation(any());verify(persistence,never()).save(any(InvestmentPosition.class));}
    @Test void revisedSourceQuoteProducesANewAuditableFingerprint(){var position=fund();var first=calculator.calculate(position,LocalDate.of(2026,10,14));quote=new InvestmentQuote(fundId,LocalDate.of(2026,10,14),decimal("10.56"));assertThat(calculator.calculate(position,LocalDate.of(2026,10,14)).calculationFingerprint()).isNotEqualTo(first.calculationFingerprint());}
    @Test void datesBeforeApplicationAreUnavailable(){assertThat(calculator.calculate(cdb(360),applied.minusDays(1)).errorCode()).isEqualTo("INVESTMENT_VALUATION_DATE");}
    @Test void invalidSourceBasisAndReversedValidityAreRejected(){assertThatIllegalArgumentException().isThrownBy(()->new InvestmentCdiPeriod(applied,applied,BigDecimal.ONE,365,"INVALID"));assertThatIllegalArgumentException().isThrownBy(()->new InvestmentCdiPeriod(applied,applied.minusDays(1),BigDecimal.ONE,252,"INVALID"));}
    @Test void overflowIsUnavailableInsteadOfReturningAnUnpersistableAmount(){quote=new InvestmentQuote(fundId,applied,decimal("1000000000000000"));assertThat(calculator.calculate(fund(),applied).errorCode()).isEqualTo("INVESTMENT_VALUATION_OVERFLOW");}
    private InvestmentPosition fund(){var p=new InvestmentProduct(fundId,"Fundo",InvestmentProduct.Type.FUND,decimal("100"),decimal("100"),"MODERATE",true,new InvestmentProduct.FundTerms(0,0,1),null);return new InvestmentPosition(UUID.randomUUID(),UUID.randomUUID(),customer,account,p,decimal("1000.00"),applied,decimal("100"),decimal("10"),applied,null);}
    private InvestmentPosition cdb(int days){return cdbAt(applied,applied.plusDays(days));}
    private InvestmentPosition cdbAt(LocalDate start,LocalDate end){var p=new InvestmentProduct(cdbId,"CDB",InvestmentProduct.Type.CDB,decimal("500"),decimal("500"),"LOW",true,null,new InvestmentProduct.CdbTerms(decimal("110"),360,"AT_MATURITY"));return new InvestmentPosition(UUID.randomUUID(),UUID.randomUUID(),customer,account,p,decimal("1000.00"),start,null,null,null,end);}
    private static InvestmentCdiPeriod rate(String from,String through,String factor,String version){return new InvestmentCdiPeriod(LocalDate.parse(from),LocalDate.parse(through),decimal(factor),252,version);}
    private static BigDecimal decimal(String value){return new BigDecimal(value);}
}
